write('tests/node/diagnostics.test.mjs', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport {DIAGNOSTICS_SCHEMA,diagnosticErrorFields,makeDiagnosticEvent,pushDiagnostic} from '../../public/js/diagnostics.js';\n\ntest('diagnostics v2 is privacy bounded and removes sensitive field names',()=>{\n  assert.equal(DIAGNOSTICS_SCHEMA,'cosmic-web-diagnostics-2');\n  const e=makeDiagnosticEvent('chunk',{fileRef:'f-123',apiKey:'SECRET',prompt:'private',filename:'person.mp3',authorization:'Bearer X',openaiRequestId:'req_123',big:'x'.repeat(500)},{now:()=> '2026-01-01T00:00:00.000Z',elapsedMs:12.4});\n  assert.equal(e.fileRef,'f-123');assert.equal(e.openaiRequestId,'req_123');assert.equal(e.apiKey,undefined);assert.equal(e.prompt,undefined);assert.equal(e.filename,undefined);assert.equal(e.authorization,undefined);assert.equal(e.big.length,300);assert.equal(e.pageElapsedMs,12);\n});\n\ntest('diagnostic ring buffer remains bounded',()=>{const events=[];for(let i=0;i<150;i++)pushDiagnostic(events,{i},100);assert.equal(events.length,100);assert.equal(events[0].i,50)});\ntest('error diagnostics omit messages but retain classification',()=>assert.deepEqual(diagnosticErrorFields({name:'TypeError',code:'browser_network_error',status:502,message:'private filename'}),{code:'browser_network_error',errorName:'TypeError',status:502}));\n")
write('tests/node/transport-policy.test.mjs', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport {applyTransportClassification,classifyTransportFailure,isExplicitUserCancellation} from '../../public/js/transport-policy.js';\n\ntest('explicit user abort is distinct from a browser transport abort',()=>{\n  const c=new AbortController();c.abort('user cancellation');\n  const err=new DOMException('Aborted','AbortError');\n  const user=classifyTransportFailure(err,{cancelRequested:true,signal:c.signal,online:true});\n  assert.equal(user.code,'user_cancelled');assert.equal(user.userCancelled,true);assert.equal(user.billingAmbiguous,true);\n  const transport=classifyTransportFailure(new DOMException('Aborted','AbortError'),{cancelRequested:false,signal:new AbortController().signal,online:true});\n  assert.equal(transport.code,'browser_transport_abort');assert.equal(transport.userCancelled,false);assert.equal(transport.billingAmbiguous,true);\n});\n\ntest('browser TypeError is a diagnosable ambiguous network failure',()=>{\n  const e=new TypeError('Failed to fetch');\n  const c=applyTransportClassification(e,{cancelRequested:false,signal:new AbortController().signal,online:true});\n  assert.equal(c.code,'browser_network_error');assert.equal(e.code,'browser_network_error');assert.equal(isExplicitUserCancellation(e),false);\n});\n\ntest('offline browser failure is classified separately',()=>assert.equal(classifyTransportFailure(new TypeError('fetch'),{online:false}).code,'browser_offline'));\n")
